// 风雪观测站。山脊和旧棚各有一项可带入后续的线索。
function snowChoice(text, next, result, {
  blood = 0, spirit = 0, favor = 0, flags = [],
  requiredSpirit = 0, requiredFlag = '', requiredReason = '',
} = {}) {
  return { text, next, result, blood, spirit, favor, flags, requiredSpirit, requiredFlag, requiredReason };
}

function snowScene(title, paragraphs, choices = []) {
  return { title, text: paragraphs.join('\n\n'), choices, ending: choices.length === 0 };
}

